import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for a in me if a == 'D')

    # Final few rounds: exploit opponents who have been reliably cooperative.
    if n >= 96:
        if opp_d <= 2:
            return 'D'
        last_op = opp[-1]
        if last_op == 'C' and opp_d * 4 < n:
            return 'D'
        return 'C' if last_op == 'C' else 'D'

    # Strongly cooperative opponent: mostly cooperate, small late probes.
    if opp_d == 0:
        if n >= 85 and rng.random() < 0.35:
            return 'D'
        if n >= 60 and rng.random() < 0.10:
            return 'D'
        return 'C'

    # Persistent defector: defend, but probe occasionally for renewed cooperation.
    recent = history[-8:] if n >= 8 else history
    rec_opp_c = sum(1 for a, b in recent if b == 'C')
    rec_opp_d = len(recent) - rec_opp_c

    if rec_opp_d >= 6 or (n >= 6 and opp_c == 0):
        if opp[-1] == 'C' and rng.random() < 0.6:
            return 'C'
        if n > 85 and rng.random() < 0.25:
            return 'C'
        return 'D'

    last_me, last_op = history[-1]

    # Opponent defected last: punish briefly, then seek repair.
    if last_op == 'D':
        # If mutual defection has dragged on, try a conciliatory C to break the loop.
        if last_me == 'D':
            # If opponent's defection is recent and not too frequent, forgive.
            if rec_opp_d <= 2 and rec_opp_c >= 3:
                return 'C'
            if rec_opp_d >= 7:
                return 'C' if rng.random() < 0.35 else 'D'
            # Short alternating retaliation can spiral; occasionally reset.
            if rng.random() < 0.18:
                return 'C'
            return 'D'
        # We cooperated, they defected. Retaliate, but forgive if rare.
        if rec_opp_d <= 1 and opp_d * 6 < n:
            return 'C' if rng.random() < 0.5 else 'D'
        return 'D'

    # Opponent cooperated last. Preserve mutual cooperation.
    if last_me == 'D':
        # Repair: return to cooperation after our own defection.
        return 'C'

    # Main cooperative regime. Rare probes, concentrated when exploitable.
    if n >= 12 and opp_d * 8 < n and my_d == 0:
        # Opponent is very cooperative; probe occasionally for extra points.
        if rng.random() < 0.04:
            return 'D'
    return 'C'
